from collections import deque
import random


class _RollbackDSU:
    __slots__ = ("parent", "size", "changes")

    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n
        self.changes = []  # (child_root, parent_root)

    def find(self, x: int) -> int:
        p = self.parent
        while p[x] != x:
            x = p[x]
        return x

    def union(self, a: int, b: int) -> None:
        a = self.find(a)
        b = self.find(b)
        if a == b:
            return
        if self.size[a] < self.size[b]:
            a, b = b, a
        self.parent[b] = a
        self.size[a] += self.size[b]
        self.changes.append((b, a))

    def mark(self) -> int:
        return len(self.changes)

    def rollback(self, mark: int) -> None:
        p, s, ch = self.parent, self.size, self.changes
        while len(ch) > mark:
            child, root = ch.pop()
            p[child] = child
            s[root] -= s[child]

    def connected(self, a: int, b: int) -> bool:
        return self.find(a) == self.find(b)


def solve(n: int, operations: list[tuple[str, int, int]]) -> list[bool]:
    m = len(operations)
    if m == 0 or n == 0:
        return []

    count = {}   # canonical edge -> positive reference count
    start = {}   # canonical edge -> operation index that made it positive
    intervals = []  # (left_inclusive_query_time, right_exclusive_query_time, edge_key)

    for i, op in enumerate(operations):
        kind = op[0]
        if kind == "connected":
            continue
        u, v = op[1], op[2]
        if u > v:
            u, v = v, u
        key = u * n + v

        if kind == "add":
            c = count.get(key)
            if c is None:
                count[key] = 1
                start[key] = i
            else:
                count[key] = c + 1
        else:  # "remove"
            c = count.get(key)
            if c is None:
                continue  # removing a zero-count edge is a no-op
            if c == 1:
                del count[key]
                s = start.pop(key)
                if s + 1 < i:
                    intervals.append((s + 1, i, key))
            else:
                count[key] = c - 1

    # Edges still positive are active until the end.
    for key, s in start.items():
        if s + 1 < m:
            intervals.append((s + 1, m, key))

    size = 1 << (m - 1).bit_length()
    tree = [[] for _ in range(2 * size)]

    for l, r, key in intervals:
        l += size
        r += size
        while l < r:
            if l & 1:
                tree[l].append(key)
                l += 1
            if r & 1:
                r -= 1
                tree[r].append(key)
            l >>= 1
            r >>= 1

    dsu = _RollbackDSU(n)
    ans = []

    def dfs(node: int, lo: int, hi: int) -> None:
        mark = dsu.mark()
        for key in tree[node]:
            a, b = divmod(key, n)
            dsu.union(a, b)

        if hi - lo == 1:
            t = lo
            if t < m and operations[t][0] == "connected":
                ans.append(dsu.connected(operations[t][1], operations[t][2]))
        else:
            mid = (lo + hi) >> 1
            dfs(node << 1, lo, mid)
            dfs(node << 1 | 1, mid, hi)

        dsu.rollback(mark)

    dfs(1, 0, size)
    return ans


def _oracle(n: int, operations: list[tuple[str, int, int]]) -> list[bool]:
    count = {}
    out = []
    for kind, u, v in operations:
        if u > v:
            u, v = v, u
        if kind == "add":
            count[(u, v)] = count.get((u, v), 0) + 1
        elif kind == "remove":
            c = count.get((u, v), 0)
            if c > 1:
                count[(u, v)] = c - 1
            elif c == 1:
                del count[(u, v)]
        else:
            if u == v:
                out.append(True)
                continue
            adj = [[] for _ in range(n)]
            for a, b in count:
                adj[a].append(b)
                adj[b].append(a)
            seen = [False] * n
            seen[u] = True
            dq = deque([u])
            while dq:
                x = dq.popleft()
                for y in adj[x]:
                    if not seen[y]:
                        seen[y] = True
                        dq.append(y)
            out.append(seen[v])
    return out


