from collections import defaultdict

class RollbackDSU:
    """Union by rank, no path compression. Each union pushes one undo record."""

    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if a == b:
            self.history.append(None)
            return
        if self.rank[a] < self.rank[b]:
            a, b = b, a
        self.history.append((b, self.parent[b], a, self.rank[a]))
        self.parent[b] = a
        if self.rank[a] == self.rank[b]:
            self.rank[a] += 1

    def rollback(self, checkpoint):
        while len(self.history) > checkpoint:
            change = self.history.pop()
            if change is None:
                continue
            b, old_parent, a, old_rank = change
            self.parent[b] = old_parent
            self.rank[a] = old_rank


def _active_intervals(operations):
    """Return (L, R, u, v) with u < v, edge present for query indices in [L, R)."""
    m = len(operations)
    count = defaultdict(int)
    started = {}
    intervals = []
    for i, op in enumerate(operations):
        kind = op[0]
        if kind not in ("add", "remove"):
            continue
        u, v = op[1], op[2]
        if u == v:
            continue  # self-loops never change connectivity
        if u > v:
            u, v = v, u
        key = (u, v)
        if kind == "add":
            if count[key] == 0:
                started[key] = i + 1  # visible only to later operations
            count[key] += 1
        else:
            if count[key] == 0:
                continue  # remove of a zero-count edge is a no-op
            count[key] -= 1
            if count[key] == 0:
                left = started.pop(key)
                right = i + 1
                if left < right:
                    intervals.append((left, right, u, v))
    for (u, v), left in started.items():
        if left < m:
            intervals.append((left, m, u, v))  # still active at the end
    return intervals


def solve(n, operations):
    m = len(operations)
    if m == 0:
        return []
    intervals = _active_intervals(operations)
    size = 1
    while size < m:
        size *= 1
        size <<= 1  # keep the shift obvious; size is the next power of two
    # fix accidental double update if the line above is misread: recompute cleanly
    size = 1
    while size < m:
        size *= 2
    tree = [[] for _ in range(2 * size)]

    def add_interval(node, nl, nr, left, right, u, v):
        if left >= right or right <= nl or nr <= left:
            return
        if left <= nl and nr <= right:
            tree[node].append((u, v))
            return
        mid = (nl + nr) // 2
        add_interval(node * 2, nl, mid, left, right, u, v)
        add_interval(node * 2 + 1, mid, nr, left, right, u, v)

    for left, right, u, v in intervals:
        add_interval(1, 0, size, left, right, u, v)

    dsu = RollbackDSU(n)
    answers = []

    def dfs(node, nl, nr):
        checkpoint = len(dsu.history)
        for u, v in tree[node]:
            dsu.union(u, v)
        if nr - nl == 1:
            if nl < m and operations[nl][0] == "connected":
                u, v = operations[nl][1], operations[nl][2]
                answers.append(dsu.find(u) == dsu.find(v))
        else:
            mid = (nl + nr) // 2
            dfs(node * 2, nl, mid)
            dfs(node * 2 + 1, mid, nr)
        dsu.rollback(checkpoint)

    dfs(1, 0, size)
    return answers


def _oracle(n, operations):
    count = defaultdict(int)
    active = set()
    answers = []
    for op in operations:
        kind, u, v = op[0], op[1], op[2]
        key = (u, v) if u < v else (v, u)
        if kind == "add":
            count[key] += 1
            if count[key] == 1 and u != v:
                active.add(key)
        elif kind == "remove":
            if count[key] > 0:
                count[key] -= 1
                if count[key] == 0:
                    active.discard(key)
        else:
            if u == v:
                answers.append(True)
                continue
            seen = [False] * n
            stack = [u]
            seen[u] = True
            found = False
            while stack:
                x = stack.pop()
                if x == v:
                    found = True
                    break
                for a, b in active:
                    y = b if a == x else a if b == x else None
                    if y is not None and not seen[y]:
                        seen[y] = True
                        stack.append(y)
            answers.append(found)
    return answers


