from collections.abc import Sequence
import random


def solve(n: int, operations: Sequence[tuple[str, int, int]]) -> list[bool]:
    """Return connectivity answers for an initially empty undirected multigraph."""
    q = len(operations)
    if q == 0:
        return []

    # Iterative segment tree over operation indices [0, q).
    base = 1
    while base < q:
        base *= 2
    buckets: list[list[tuple[int, int]]] = [[] for _ in range(2 * base)]

    def add_interval(left: int, right: int, edge: tuple[int, int]) -> None:
        """Put edge in canonical segment-tree nodes covering [left, right)."""
        if left >= right:
            return
        left += base
        right += base
        while left < right:
            if left & 1:
                buckets[left].append(edge)
                left += 1
            if right & 1:
                right -= 1
                buckets[right].append(edge)
            left //= 2
            right //= 2

    # For each currently present edge: [reference_count, active_interval_start].
    active: dict[tuple[int, int], list[int]] = {}

    for t, (kind, u, v) in enumerate(operations):
        edge = (min(u, v), max(u, v))
        if kind == "add":
            state = active.get(edge)
            if state is None:
                active[edge] = [1, t]
            else:
                state[0] += 1
        elif kind == "remove":
            state = active.get(edge)
            if state is not None:
                if state[0] == 1:
                    add_interval(state[1], t, edge)
                    del active[edge]
                else:
                    state[0] -= 1

    # Edges still present remain active through the final operation.
    for edge, state in active.items():
        add_interval(state[1], q, edge)

    parent = list(range(n))
    component_size = [1] * n
    history: list[tuple[int, int, int]] = []

    def find(x: int) -> int:
        # Deliberately no path compression: every changed parent is rollbackable.
        while parent[x] != x:
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        a = find(a)
        b = find(b)
        if a == b:
            return
        if component_size[a] < component_size[b]:
            a, b = b, a
        history.append((b, a, component_size[a]))
        parent[b] = a
        component_size[a] += component_size[b]

    def rollback(snapshot: int) -> None:
        while len(history) > snapshot:
            child, root, old_size = history.pop()
            parent[child] = child
            component_size[root] = old_size

    answers: list[bool] = []

    def visit(node: int, left: int, right: int) -> None:
        snapshot = len(history)
        for u, v in buckets[node]:
            union(u, v)

        if right - left == 1:
            if left < q and operations[left][0] == "connected":
                _, u, v = operations[left]
                answers.append(find(u) == find(v))
        else:
            middle = (left + right) // 2
            visit(node * 2, left, middle)
            visit(node * 2 + 1, middle, right)

        rollback(snapshot)

    visit(1, 0, base)
    return answers


# Deterministic and randomized differential tests.
def _bfs_oracle(n: int, operations: Sequence[tuple[str, int, int]]) -> list[bool]:
    counts: dict[tuple[int, int], int] = {}
    answers: list[bool] = []

    for kind, u, v in operations:
        edge = (min(u, v), max(u, v))
        if kind == "add":
            counts[edge] = counts.get(edge, 0) + 1
        elif kind == "remove":
            if counts.get(edge, 0) > 1:
                counts[edge] -= 1
            else:
                counts.pop(edge, None)
        else:
            adjacency = [[] for _ in range(n)]
            for (a, b), count in counts.items():
                if count:
                    adjacency[a].append(b)
                    adjacency[b].append(a)

            seen = {u}
            stack = [u]
            while stack:
                x = stack.pop()
                for y in adjacency[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
            answers.append(v in seen)

    return answers


def _run_tests() -> None:
