    # Reversed endpoints, repeated additions, removal to zero, and extra no-op removal.
    ops = [
        ("connected", 0, 1),
        ("add", 0, 1),
        ("add", 1, 0),
        ("remove", 0, 1),
        ("connected", 1, 0),
        ("remove", 1, 0),
        ("connected", 0, 1),
        ("remove", 0, 1),
        ("connected", 0, 1),
        ("add", 2, 2),
        ("connected", 2, 2),
    ]
    assert solve(3, ops) == [False, True, False, False, True]

    # Edges stay active until the end, and connect components transitively.
    ops = [
        ("add", 0, 1),
        ("connected", 0, 1),
        ("add", 1, 2),
        ("connected", 0, 2),
    ]
    assert solve(3, ops) == [True, True]

    # A self-loop does not connect distinct vertices.
    ops = [("add", 0, 0), ("connected", 0, 1)]
    assert solve(2, ops) == [False]

    rng = random.Random(20250308)
    for _ in range(300):
