        ops = []
        for _ in range(rng.randint(0, 60)):
            kind = rng.choice(("add", "remove", "connected"))
            ops.append((kind, rng.randrange(n), rng.randrange(n)))
        assert solve(n, ops) == _bfs_oracle(n, ops)

    print("all tests passed")


