def solve(n, operations):
    """Return answers to connected queries in input order."""
    m = len(operations)
    if m == 0:
        return []

    # Iterative segment tree. A node stores edges active throughout
    # that node's time range.
    base = 1 << (m - 1).bit_length()
    tree = [None] * (2 * base)

    def add_interval(left, right, edge):
        left += base
        right += base
        while left < right:
            if left & 1:
                if tree[left] is None:
                    tree[left] = []
                tree[left].append(edge)
                left += 1
            if right & 1:
                right -= 1
                if tree[right] is None:
                    tree[right] = []
                tree[right].append(edge)
            left //= 2
            right //= 2

    # active[edge] = [positive reference count, start time].
    active = {}
    for t, (kind, u, v) in enumerate(operations):
        edge = (u, v) if u <= v else (v, u)

        if kind == "add":
            state = active.get(edge)
            if state is None:
                active[edge] = [1, t]
            else:
                state[0] += 1
        elif kind == "remove":
            state = active.get(edge)
            if state is not None:  # Removing a zero-count edge does nothing.
                if state[0] == 1:
                    add_interval(state[1], t, edge)
                    del active[edge]
                else:
                    state[0] -= 1
        # A connected operation does not change edge activity.

    for edge, (_, start) in active.items():
        add_interval(start, m, edge)

    parent = list(range(n))
    component_size = [1] * n
    history = []

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def union(u, v):
        a, b = find(u), find(v)
        if a == b:
            return
        if component_size[a] < component_size[b]:
            a, b = b, a
        parent[b] = a
        component_size[a] += component_size[b]
        history.append((b, a))

    def rollback(snapshot):
        while len(history) > snapshot:
            child, root = history.pop()
            parent[child] = child
            component_size[root] -= component_size[child]

    answers = []

    def visit(node, left, right):
        if left >= m:
            return

        snapshot = len(history)
        if tree[node] is not None:
            for u, v in tree[node]:
                union(u, v)

        if right - left == 1:
            kind, u, v = operations[left]
            if kind == "connected":
                answers.append(find(u) == find(v))
        else:
            middle = (left + right) // 2
            visit(2 * node, left, middle)
            visit(2 * node + 1, middle, right)

        rollback(snapshot)

    visit(1, 0, base)
    return answers


